// Parse GitHub event type and build agent message
const body = $input.first().json.body || $input.first().json;
const event = $input.first().headers?.['x-github-event'] || 'push';

let agentId = 'eng';
let message = '';

if (event === 'push') {
  const repo = body.repository?.full_name || 'unknown';
  const branch = body.ref?.replace('refs/heads/', '') || 'unknown';
  const commits = (body.commits || []).slice(0, 3).map(c => `- ${c.message}`).join('\n');
  agentId = 'eng';
  message = `GITHUB PUSH to ${repo}/${branch}:\n${commits}\n\nReview for any issues, update status in workspace/STATE.yaml if relevant.`;
} else if (event === 'pull_request') {
  const pr = body.pull_request || {};
  const action = body.action || 'opened';
  const repo = body.repository?.full_name || 'unknown';
  agentId = 'eng';
  message = `GITHUB PR #${pr.number} ${action} in ${repo}: "${pr.title}"\nAuthor: ${pr.user?.login}\nBranch: ${pr.head?.ref} → ${pr.base?.ref}\n\nReview for code quality and merge readiness. Coordinate with INFOSEC if security-related.`;
} else if (event === 'issues') {
  const issue = body.issue || {};
  const action = body.action || 'opened';
  agentId = 'ops';
  message = `GITHUB ISSUE #${issue.number} ${action}: "${issue.title}"\nBody: ${(issue.body || '').substring(0, 200)}\n\nTriage and create ticket in TICKET-TRACKER.md if action required.`;
}

return [{ json: { agentId, message, event, repo: body.repository?.full_name } }];
